import io.github.cheshmakzanoon.portfolio.quorumkv.*;
class Debug{public static void main(String[]a)throws Exception{Simulator s=new Simulator(417);try{s.faultSchedule(180);}catch(Throwable e){System.out.println(e.getMessage());}for(int i=0;i<3;i++){Raft n=s.node(i);System.out.println(i+" role="+n.role()+" term="+n.term()+" disk="+n.waitingForDisk()+" commit="+n.commit()+" applied="+n.applied());for(var f:Raft.class.getDeclaredFields())if(java.util.Set.of("pendingPersist","deadline","deferred","clock").contains(f.getName())){f.setAccessible(true);System.out.println(f.getName()+" "+f.get(n));}}s.run(5000);System.out.println("after leader="+s.leader());}}
